<?php
declare(strict_types=1);
require_once __DIR__.'/bootstrap/app.php';
$rows=$pdo->query("SELECT c.id,c.title,s.creative_json,s.placement_key FROM pf_campaigns c JOIN pf_site_campaigns s ON s.campaign_id=c.id WHERE c.campaign_type='SITE_DISPLAY' AND c.status='ACTIVE' AND s.status='ACTIVE' AND s.placement_key='main_directory_inline' AND s.starts_at<=NOW() AND s.ends_at>=NOW() ORDER BY c.created_at DESC LIMIT 50")->fetchAll();
?>
